"""Write progress.json: which works in the library are still being produced.

The reader marks these works "in progress" in the library and on each of their parts.
Rule (Zev, 2026-10-18): every work that is not finished is marked automatically, and the
mark comes off by itself once the work is finished. Nothing here needs editing per work.

  * A work with a production folder in .github/pipeline/<name>/ is in progress until that
    folder holds a DONE file (the runs write DONE when a work's last part is published).
  * A work with no production folder is finished, except the few listed in NOT_FINISHED,
    which are single pieces of longer texts that no run is producing.

For each work in progress the file also gives how many parts are published and, where the
production folder lists the planned parts, how many there will be.

Run from the repository root:  python3 .github/scripts/build_progress.py
"""
import json, os

PIPE = ".github/pipeline"
NOT_A_WORK = {"run3"}                    # tooling folders, not works
# Works with no production folder that are excerpts of a longer text (story id prefixes).
NOT_FINISHED = ("aqhat", "ani-")


def main():
    stories = json.load(open("stories.json", encoding="utf-8"))["stories"]
    by_id = {s["id"]: s for s in stories}
    status = {}   # workEn -> {"published": n, "planned": n or None}

    for name in sorted(os.listdir(PIPE)):
        folder = os.path.join(PIPE, name)
        if not os.path.isdir(folder) or name in NOT_A_WORK:
            continue
        if os.path.exists(os.path.join(folder, "DONE")):
            continue
        planned = set()
        pj = os.path.join(folder, "parts.json")
        if os.path.exists(pj):
            parts = json.load(open(pj, encoding="utf-8")).get("parts", [])
            planned = {p["id"] for p in parts if isinstance(p, dict) and p.get("id")}
        # The work's published parts: ids listed in parts.json, or ids starting with the folder name.
        mine = [s for s in stories if s["id"] in planned or s["id"].startswith(name)]
        if not mine:
            continue
        work = mine[0]["workEn"]
        published = [s for s in stories if s["workEn"] == work]
        # parts.json of the later runs omits the pilot part, so count the union.
        total = len(planned | {s["id"] for s in published}) if planned else None
        status[work] = {"published": len(published), "planned": total}

    for s in stories:
        if s["id"].startswith(NOT_FINISHED) and s["workEn"] not in status:
            n = sum(1 for x in stories if x["workEn"] == s["workEn"])
            status[s["workEn"]] = {"published": n, "planned": None}

    out = {"note": "Generated by .github/scripts/build_progress.py; do not edit by hand.",
           "inProgress": dict(sorted(status.items()))}
    new = json.dumps(out, ensure_ascii=False, indent=1) + "\n"
    old = open("progress.json", encoding="utf-8").read() if os.path.exists("progress.json") else ""
    if new != old:
        open("progress.json", "w", encoding="utf-8").write(new)
        print("progress.json updated")
    else:
        print("progress.json unchanged")
    for w, v in status.items():
        print("  in progress:", w, v)


if __name__ == "__main__":
    main()
